package com.lqq.supportflow.knowledge.api;
import com.lqq.supportflow.knowledge.application.SearchKnowledgeBaseService; import com.lqq.supportflow.knowledge.domain.KnowledgeSearchResult; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/knowledge-bases/{knowledgeBaseId}/search") public class KnowledgeSearchController { private final SearchKnowledgeBaseService service; public KnowledgeSearchController(SearchKnowledgeBaseService service){this.service=service;} @PostMapping KnowledgeSearchResult search(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long knowledgeBaseId,@Valid @RequestBody SearchKnowledgeRequest request){return service.search(principal.tenantId(),knowledgeBaseId,request.query());}}
